<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class ShippingZone extends Model{protected $fillable=['name','states','rate','free_shipping_minimum','estimated_days','active'];protected $casts=['states'=>'array','rate'=>'decimal:2','free_shipping_minimum'=>'decimal:2','active'=>'boolean'];public function calculate(float $subtotal):float{return $this->free_shipping_minimum!==null&&$subtotal>=$this->free_shipping_minimum?0:(float)$this->rate;}}
